/**
 * Invoice Detail: the read-only invoice with Download / Share.
 *
 * Gate (FINAL_LIST row 4): read-only; Download and Share render for
 * invoice.view_own. Generated By and the timeline render only when the record
 * carries them. Scope: a Sub scope only opens invoices of its own warehouse;
 * any other id shows "not found" (an empty result, never a 403-style "not
 * allowed", CLAUDE.md 2.1). The server enforces the same.
 *
 * Absorbs (pairs M9-S03, M9-S06):
 *   - Main InvoiceDetailScreen: same sections; its privacy note is ported for
 *     the Main view (scope.warehouseId undefined).
 *   - Main DownloadInvoiceScreen and Sub SubWarehouseInvoicePreviewScreen: the
 *     Download action here (with the "Invoice downloaded" toast from Preview);
 *     Main's signed-link note is ported for the Main view.
 *   - Sub SubWarehouseInvoiceHistoryDetailScreen: its Invoice Type, Generated
 *     By, Status and Download Availability fields are in Invoice Information.
 *     The Sub shell's history-detail and preview flows open this screen with
 *     the invoice id.
 */
// Design id: M9-S03
import React, { useEffect, useState } from 'react';
import { Alert, BackHandler, ScrollView, StyleSheet, Text, View } from 'react-native';

import { adminColors, adminRadius, adminSpacing, adminType } from '../../../theme';
import {
  BillingButton,
  BillingFooter,
  BillingScreen,
  BillingToast,
  Card,
  DownloadIcon,
  HeaderIconButton,
  InfoCard,
  isAllWarehouses,
  PermissionNote,
  SectionTitle,
} from './BillingParts';
import type { InvoiceDetailRecord, WarehouseScreenBaseProps } from './types';

export interface InvoiceDetailScreenProps extends WarehouseScreenBaseProps {
  invoiceId: string;
  /** Detail record; defaults to the mock invoice until the invoice API is wired. */
  invoice?: InvoiceDetailRecord | undefined;
  onDownload?: ((invoiceId: string) => void) | undefined;
  onShare?: ((invoiceId: string) => void) | undefined;
}

import { useInvoiceDetail } from './useBillingData';

export function InvoiceDetailScreen({
  scope,
  can,
  onBack,
  invoiceId,
  invoice: invoiceProp,
  onDownload,
  onShare,
}: InvoiceDetailScreenProps) {
  const [showPreview, setShowPreview] = useState(false);
  const [showToast, setShowToast] = useState(false);

  const { invoice: liveInvoice, isLoading, downloadPdf } = useInvoiceDetail(invoiceId, !invoiceProp);
  const invoice = invoiceProp ?? liveInvoice;

  useEffect(() => {
    if (!showPreview) return;
    const sub = BackHandler.addEventListener('hardwareBackPress', () => {
      setShowPreview(false);
      return true;
    });
    return () => sub.remove();
  }, [showPreview]);

  const canView = can('invoice.view_own');
  const allWarehouses = isAllWarehouses(scope);

  if (isLoading && !invoiceProp) {
    return (
      <BillingScreen title="Invoice Detail" onBack={onBack}>
        <View style={styles.scrollContent}>
          <PermissionNote>Loading invoice…</PermissionNote>
        </View>
      </BillingScreen>
    );
  }

  if (!invoice) {
    return (
      <BillingScreen title="Invoice Detail" onBack={onBack}>
        <View style={styles.scrollContent}>
          <PermissionNote>Invoice not found.</PermissionNote>
        </View>
      </BillingScreen>
    );
  }

  const record = invoice;

  const handleDismissToast = React.useCallback(() => {
    setShowToast(false);
  }, []);

  const handlePdfDownload = () => {
    setShowToast(true);
    if (onDownload) {
      onDownload(invoiceId);
    } else {
      void downloadPdf();
    }
  };

  const handleDownload = () => {
    if (!allWarehouses) {
      setShowPreview(true);
      return;
    }
    handlePdfDownload();
  };

  const handleShare = () => (onShare ? onShare(invoiceId) : Alert.alert('Share', `Sharing ${invoiceId}...`));

  if (showPreview) {
    return (
      <BillingScreen
        title="Invoice Preview"
        onBack={() => setShowPreview(false)}
        toast={
          showToast ? (
            <BillingToast
              message="Invoice downloaded"
              visible={showToast}
              onDismiss={handleDismissToast}
            />
          ) : null
        }
        footer={
          canView ? (
            <BillingFooter>
              <BillingButton label="Download PDF" icon={<DownloadIcon />} onPress={handlePdfDownload} />
              <BillingButton label="Share" variant="outline" onPress={handleShare} />
            </BillingFooter>
          ) : null
        }
      >
        <ScrollView contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
          <Card style={styles.previewCard}>
            <View style={styles.previewHeader}>
              <Text style={styles.previewBrandTitle}>TOHFA</Text>
              <Text style={styles.previewDocLabel}>Invoice · {record.invoiceNumber}</Text>
              <View style={styles.brandDivider} />
            </View>

            {record.customerName ? (
              <View style={styles.previewRow}>
                <Text style={styles.previewLabel}>Customer</Text>
                <Text style={styles.previewValue}>{record.customerName}</Text>
              </View>
            ) : null}

            {record.items.map((item, index) => (
              <View key={`${item.name}-${index}`} style={styles.previewRow}>
                <Text style={styles.previewLabel}>
                  {item.name} · {item.quantity}
                </Text>
                <Text style={styles.previewValue}>{item.lineTotal}</Text>
              </View>
            ))}

            <Text style={styles.previewGrandTotal}>{record.total}</Text>
          </Card>
        </ScrollView>
      </BillingScreen>
    );
  }

  const infoRows = [
    [
      { label: 'Invoice Number', value: record.invoiceNumber },
      { label: 'Order Reference', value: record.orderId ?? '—' },
    ],
    [
      { label: 'Date', value: record.date },
      { label: 'Invoice Type', value: record.typeLabel },
    ],
    [
      { label: 'Status', value: record.statusLabel },
      { label: 'Download', value: record.downloadAvailable ? 'Available' : 'Unavailable' },
    ],
    ...(record.placeOfSupply ? [[{ label: 'Place of Supply', value: record.placeOfSupply }]] : []),
  ];

  return (
    <BillingScreen
      title="Invoice Detail"
      subtitle={`${record.invoiceNumber} · ${record.statusLabel}`}
      onBack={onBack}
      headerRight={
        canView ? (
          <HeaderIconButton onPress={handleDownload} accessibilityLabel="Download Invoice">
            <DownloadIcon />
          </HeaderIconButton>
        ) : null
      }
      toast={
        showToast ? (
          <BillingToast
            message="Invoice downloaded"
            visible={showToast}
            onDismiss={handleDismissToast}
          />
        ) : null
      }
      footer={
        canView ? (
          <BillingFooter>
            <BillingButton label="Download Invoice" icon={<DownloadIcon />} onPress={handleDownload} />
            <BillingButton label="Share" variant="outline" onPress={handleShare} />
          </BillingFooter>
        ) : null
      }
    >
      <ScrollView contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
        <View style={styles.brandBlock}>
          <Text style={styles.brandTitle}>TOHFA</Text>
          <Text style={styles.brandSubtitle}>Nilgiris Horticulture Organic Farmers Association</Text>
          <View style={styles.brandDivider} />
          <Text style={styles.invoiceDocLabel}>Invoice · {record.invoiceNumber}</Text>
        </View>

        <SectionTitle>Invoice Information</SectionTitle>
        <InfoCard rows={infoRows} />

        {record.buyerName ? (
          <>
            <SectionTitle>Bill To</SectionTitle>
            <Card>
              <Text style={styles.billToName}>{record.buyerName}</Text>
              {record.buyerGstin ? (
                <Text style={styles.billToDetails}>GSTIN: {record.buyerGstin}</Text>
              ) : null}
            </Card>
          </>
        ) : null}

        <SectionTitle>Product / Line Items</SectionTitle>
        <Card>
          {record.items.map((item, index) => (
            <View key={`${item.name}-${index}`}>
              {index > 0 ? <View style={styles.divider} /> : null}
              <View style={styles.itemRow}>
                <View style={styles.itemLeft}>
                  <Text style={styles.itemName}>{item.name}</Text>
                  {item.hsn ? <Text style={styles.itemMeta}>{item.hsn}</Text> : null}
                  <Text style={styles.itemMeta}>
                    {item.quantity} × {item.unitPrice}
                  </Text>
                </View>
                <Text style={styles.itemPrice}>{item.lineTotal}</Text>
              </View>
            </View>
          ))}
        </Card>

        <SectionTitle>Amount Summary</SectionTitle>
        <Card>
          {[
            ['Taxable Amount', record.taxable],
            ['CGST', record.cgst],
            ['SGST', record.sgst],
            ['IGST', record.igst],
            ['GST', record.gst],
          ].map(([label, value]) => (
            <View key={label} style={styles.summaryRow}>
              <Text style={styles.summaryLabel}>{label}</Text>
              <Text style={styles.summaryValue}>{value}</Text>
            </View>
          ))}
          <View style={styles.divider} />
          <View style={styles.summaryRow}>
            <Text style={styles.totalLabel}>Total</Text>
            <Text style={styles.totalValue}>{record.total}</Text>
          </View>
        </Card>
      </ScrollView>
    </BillingScreen>
  );
}

const TIMELINE_LINE_HEIGHT = 28;

const styles = StyleSheet.create({
  scrollContent: { paddingHorizontal: adminSpacing.lg, paddingTop: adminSpacing.md, paddingBottom: adminSpacing.xl },
  brandBlock: { alignItems: 'center', paddingVertical: adminSpacing.md },
  brandTitle: { ...adminType.title, color: adminColors.brand },
  brandSubtitle: { ...adminType.rowMeta, color: adminColors.muted, marginTop: 2, textAlign: 'center' },
  brandDivider: {
    alignSelf: 'stretch',
    height: 1,
    backgroundColor: adminColors.border,
    marginVertical: adminSpacing.sm,
  },
  invoiceDocLabel: { ...adminType.sectionHead, color: adminColors.ink },

  billToName: { ...adminType.rowTitle, color: adminColors.ink },
  billToDetails: { ...adminType.rowMeta, color: adminColors.muted, marginTop: 2 },

  divider: { height: 1, backgroundColor: adminColors.border, marginVertical: adminSpacing.sm },
  itemRow: { flexDirection: 'row', alignItems: 'flex-start', justifyContent: 'space-between' },
  itemLeft: { flex: 1 },
  itemName: { ...adminType.rowTitle, color: adminColors.ink },
  itemMeta: { ...adminType.rowMeta, color: adminColors.muted, marginTop: 1 },
  itemPrice: { ...adminType.sectionHead, color: adminColors.ink },

  summaryRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingVertical: adminSpacing.xs,
  },
  summaryLabel: { ...adminType.body, color: adminColors.muted },
  summaryValue: { ...adminType.rowTitle, color: adminColors.ink },
  totalLabel: { ...adminType.sectionHead, color: adminColors.ink },
  totalValue: { ...adminType.kpiValue, color: adminColors.ink },

  timelineStep: { flexDirection: 'row', alignItems: 'flex-start' },
  timelineIconCol: { alignItems: 'center', width: adminSpacing.xl },
  timelineLine: { width: 2, height: TIMELINE_LINE_HEIGHT, backgroundColor: adminColors.border, marginVertical: 2 },
  timelineContent: { flex: 1, marginLeft: adminSpacing.sm, paddingBottom: adminSpacing.md },
  timelineTitle: { ...adminType.rowTitle, color: adminColors.ink },
  timelineTime: { ...adminType.rowMeta, color: adminColors.muted, marginTop: 2 },

  generatedBy: { marginTop: adminSpacing.md, borderRadius: adminRadius.lg },

  previewCard: {
    backgroundColor: adminColors.card,
    borderRadius: adminRadius.lg,
    borderWidth: 1,
    borderColor: adminColors.border,
    paddingHorizontal: adminSpacing.lg,
    paddingTop: adminSpacing.lg,
    paddingBottom: adminSpacing.md,
    marginBottom: adminSpacing.md,
  },
  previewHeader: {
    alignItems: 'center',
    marginBottom: adminSpacing.sm,
  },
  previewBrandTitle: {
    ...adminType.title,
    color: adminColors.ink,
    textAlign: 'center',
  },
  previewDocLabel: {
    ...adminType.caption,
    color: adminColors.muted,
    marginTop: 2,
    textAlign: 'center',
  },
  previewRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingVertical: adminSpacing.sm,
  },
  previewLabel: {
    ...adminType.body,
    color: adminColors.muted,
  },
  previewValue: {
    ...adminType.rowTitle,
    fontWeight: '600',
    color: adminColors.ink,
  },
  previewGrandTotal: {
    ...adminType.kpiValue,
    color: adminColors.ink,
    textAlign: 'center',
    marginTop: adminSpacing.md,
    marginBottom: adminSpacing.sm,
  },
});
